---@class PlayerPayActivity : cls
local PlayerPayActivity = class("PlayerPayActivity")
PlayerPayActivity.tostring_overload = true
---@type PayActivityConfig
local PayActivityConfig = T(Global, "PayActivityConfig")
---@type SPayActivityPkSender
local PayActivityPkSender = T(Global, "PidPacketSender")
---@type PayActivityMgr
local PayActivityMgr = T(Global, "PayActivityMgr")

---@param player SBasePlayer | CBasePlayer
function PlayerPayActivity:ctor(player)
    player.payActivity = self
    self.player = player
    ---@type IPayActivity[]
    self.activities = {}
end

function PlayerPayActivity:initDBData(data)
    self.data = data
    local activities = PayActivityMgr:getAllActivity()
    for activityId, _ in pairs(activities) do
        self:createActivity(activityId, self.data[tostring(activityId)])
    end
end

function PlayerPayActivity:onPlayerLogout()
    for _, activity in pairs(self.activities) do
        activity:stop()
    end
end

function PlayerPayActivity:getSaveDBData()
    for activityId, activity in pairs(self.activities) do
        self.data[tostring(activityId)] = activity:getSaveDBData()
    end
    return self.data
end

---@param data any 活动数据
function PlayerPayActivity:createActivity(activityId, data)
    local cfg = PayActivityConfig:getCfgById(activityId)
    if not cfg then
        return
    end
    ---@type IPayActivity
    local IActivity = Plugins.Require("pay_activity", "common.class." .. cfg.class)
    local activity = IActivity.new(self.player, cfg)
    self.activities[activityId] = activity
    activity:setSaveDBData(data or {})
    if isServer then
        PayActivityPkSender:sendCreatePayActivity(self.player, activityId, data)
    end
    activity:start()
end

function PlayerPayActivity:removeActivity(activityId)
    local activity = self.activities[activityId]
    if not activity then
        return
    end
    if isServer then
        self.data[tostring(activityId)] = activity:getSaveDBData()
        PayActivityPkSender:sendRemovePayActivity(self.player, activityId)
    end
    activity:stop()
    self.activities[activityId] = nil

    if isClient then
        if not UIHelper.isGameGUILayoutShow("GUIPayActivity") then
            return
        end
        ---@type UIPayActivityLayout
        local GUIPayActivity = UIHelper.newGameGUILayout("GUIPayActivity")
        GUIPayActivity:removeActivity(activity)
        if not self:canShowPayActivity() then
            UIHelper.hideGameGUILayout("GUIPayActivity")
            CustomDialog.builder()
                        .setContentText(Lang:getString("common.activity.end.tip"))
                        .setHideLeftButton()
                        .show()
        end
    end
end

function PlayerPayActivity:canShowPayActivity()
    for _, activity in pairs(self.activities) do
        if activity.cfg.tabName ~= "#" then
            return true
        end
    end
    return false
end

function PlayerPayActivity:print()
    local result = "\n-----------------activity-----------------\n"
    result = result .. tostring(self)
    LogUtil.logDebug(result)
end

function PlayerPayActivity:__tostring()
    local result = "{\n"
    local content = {}
    table.insert(content, "\t" .. "userId=" .. self.player.userId .. ",")
    table.insert(content, "\t" .. "activities=[")
    for _, activity in pairs(self.activities) do
        table.insert(content, "\t\t" .. tostring(activity) .. ",")
    end
    result = result .. table.concat(content, "\n")
    result = result .. "\n\t]\n}"
    return result
end

function PlayerPayActivity:onSecondTick(curTime)
    for _, activity in pairs(self.activities) do
        activity:onSecondTick(curTime)
    end
end

function PlayerPayActivity:onWatchAdvert(type, params)
    for _, activity in pairs(self.activities) do
        activity:runServerFunc("onWatchAdvert", type, params)
    end
end

return PlayerPayActivity